import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { chromium, type Browser, type BrowserContext, type Page } from "playwright-core";
import {
  BASE_URL,
  cleanupE2EUser,
  createAnalyzedE2EProject,
  createE2EEditorDocument,
  editorTextNode,
  registerBrowserUser,
  SESSION_COOKIE,
  startStack,
  stopStack,
  type E2EStack,
  type RegisteredBrowserUser,
} from "./support/image-harness";

/**
 * Real browser proof of the CP20 AI edit flow against live CP18 grounding.
 *
 * A BODY variant is generated by the real writing worker, the editor document
 * carries a WRITING_VARIANT node, and the AI tab must (a) preview a LOCAL
 * proposal without persisting anything, (b) ground a reword before it is ever
 * applied, and (c) refuse copy whose claim the project cannot support. Applying
 * records an AI-sourced revision.
 */

let stack: E2EStack;
let user: RegisteredBrowserUser;
let browser: Browser;
let context: BrowserContext;
const projectIds: string[] = [];
let email = "";
let aiProjectId = "";
let aiDocumentId = "";
let aiJobId = "";
let variantId = "";
let variantText = "";
let sourceIds: string[] = [];
let setupDone = false;

async function openEditor(page: Page): Promise<void> {
  await page.goto(
    `${BASE_URL}/projects/${aiProjectId}/editor/${aiDocumentId}`,
    { waitUntil: "domcontentloaded" },
  );
  await page
    .getByTestId("editor-stage")
    .waitFor({ state: "visible", timeout: 15_000 });
}

async function selectGroundedNode(page: Page): Promise<void> {
  await page.getByTestId("editor-layer").first().click();
  await page
    .getByTestId("editor-inspector-text")
    .waitFor({ state: "visible", timeout: 15_000 });
}

beforeAll(async () => {
  stack = await startStack();
  if (!stack.reachable || !stack.available) return;

  const services = await import("../../src/infrastructure/services");

  email = `cp20-ai-${Date.now()}@test.local`;
  user = await registerBrowserUser(email);

  aiProjectId = await createAnalyzedE2EProject(
    user.workspaceId,
    user.userId,
    "CP20 editor AI",
  );
  projectIds.push(aiProjectId);

  // A real CP18 generation, drained by the writing worker this stack started.
  // The job is created here; its outcome is polled inside the first test,
  // because expect.poll() is only available in a test.
  const job = await services.writingGenerationService.enqueue({
    projectId: aiProjectId,
    requestedById: user.userId,
    blockType: "BODY",
    tone: "PROFESSIONAL",
    length: "LONG",
    objective: "PRODUCT_EXPLANATION",
    prompt: "Explain the product with proof",
    variantCount: 1,
    intentId: null,
    directionId: null,
    storyboardId: null,
    sceneId: null,
  });
  aiJobId = job.id;

  browser = await chromium.launch({
    executablePath: stack.executablePath,
    args: ["--no-sandbox"],
  });
  context = await browser.newContext();
  await context.addCookies([
    { name: SESSION_COOKIE, value: user.cookieValue, url: BASE_URL },
  ]);
});

afterAll(async () => {
  if (browser) await browser.close();
  stopStack(stack);
  if (user) await cleanupE2EUser(email, user.workspaceId, projectIds);
});

describe("editor AI end to end", () => {
  it("is runnable in this environment", async (testContext) => {
    if (!stack.reachable || !stack.available) {
      testContext.skip();
      return;
    }
    expect(stack.executablePath).toBeTruthy();

    const services = await import("../../src/infrastructure/services");

    await expect
      .poll(
        async () => {
          const record = await services.writingGenerationService.getJob({
            projectId: aiProjectId,
            jobId: aiJobId,
            userId: user.userId,
          });
          return record.status;
        },
        { timeout: 120_000, interval: 500 },
      )
      .toBe("SUCCEEDED");

    const view = await services.writingGenerationService.getDocument({
      projectId: aiProjectId,
      documentId: (
        await services.writingGenerationService.getJob({
          projectId: aiProjectId,
          jobId: aiJobId,
          userId: user.userId,
        })
      ).documentId!,
      userId: user.userId,
    });

    const snapshot = JSON.parse(view.document.contextSnapshot) as {
      sourceIds: string[];
    };
    sourceIds = snapshot.sourceIds;
    variantId = view.variants[0]!.id;
    variantText = view.variants[0]!.text;

    const created = await createE2EEditorDocument(
      aiProjectId,
      user.userId,
      "AI edit",
      [
        editorTextNode({
          id: "enode-ai-1",
          name: "Claim",
          text: { value: "Draft claim" },
          provenance: {
            origin: "WRITING_VARIANT",
            sourceType: "WRITING_VARIANT",
            sourceId: variantId,
            sourceIds,
            label: null,
          },
        }),
      ],
    );
    aiDocumentId = created.documentId;
    setupDone = true;
  });

  it("previews a local proposal without persisting anything", async (testContext) => {
    if (!setupDone) {
      void testContext;
      if (!stack.reachable || !stack.available) testContext.skip();
      return;
    }

    const page = await context.newPage();
    await openEditor(page);
    await selectGroundedNode(page);

    await page.getByTestId("editor-tab-ai").click();
    const input = page.getByTestId("editor-propose-input");
    await input.waitFor({ state: "visible", timeout: 15_000 });
    await input.fill("move right by 50px");
    await page.getByTestId("editor-propose-button").click();

    await page
      .getByTestId("editor-proposal-summary")
      .waitFor({ state: "visible", timeout: 15_000 });
    await expect
      .poll(
        async () =>
          page.getByTestId("editor-proposal-summary").textContent(),
        { timeout: 15_000 },
      )
      .toContain("LOCAL");
    await expect
      .poll(
        async () =>
          page.getByTestId("editor-proposal-grounding").textContent(),
        { timeout: 15_000 },
      )
      .toContain("No grounded copy context");

    // Proposals are previews: the stage and the store stay untouched.
    const services = await import("../../src/infrastructure/services");
    const head = await services.editorService.getDocument({
      projectId: aiProjectId,
      userId: user.userId,
      documentId: aiDocumentId,
    });
    expect(head.document.status).toBe("DRAFT");
    expect(head.revision.operationType).toBe("CREATE");

    await page.close();
  });

  it("grounds a reword and applies it only when told to", async (testContext) => {
    if (!setupDone) {
      void testContext;
      if (!stack.reachable || !stack.available) testContext.skip();
      return;
    }

    const page = await context.newPage();
    await openEditor(page);
    await selectGroundedNode(page);

    await page.getByTestId("editor-tab-ai").click();
    const input = page.getByTestId("editor-propose-input");
    await input.waitFor({ state: "visible", timeout: 15_000 });
    await input.fill(`set text to ${variantText}`);
    await page.getByTestId("editor-propose-button").click();

    await page
      .getByTestId("editor-proposal-grounding")
      .waitFor({ state: "visible", timeout: 15_000 });
    await expect
      .poll(
        async () =>
          page.getByTestId("editor-proposal-grounding").textContent(),
        { timeout: 15_000 },
      )
      .toContain("Supported by");

    // The node still shows the old copy — proposal is not the edit.
    const staged = page
      .locator('[data-testid="editor-node"][data-node-type="TEXT"]')
      .first();
    await expect
      .poll(async () => staged.textContent(), { timeout: 15_000 })
      .toContain("Draft claim");

    await page.getByTestId("editor-apply-button").click();
    await expect
      .poll(
        async () => page.getByTestId("editor-save-state").textContent(),
        { timeout: 15_000 },
      )
      .toBe("Saved");
    await expect
      .poll(
        async () => staged.textContent(),
        { timeout: 15_000 },
      )
      .toContain(variantText.slice(0, 40));

    // The applied proposal landed as an AI-sourced revision.
    const history = await page.request.get(
      `${BASE_URL}/api/projects/${aiProjectId}/editor/${aiDocumentId}/history`,
    );
    expect(history.status()).toBe(200);
    const body = (await history.json()) as {
      revisions: Array<{ sourceType: string; operationType: string }>;
    };
    expect(
      body.revisions.filter((revision) => revision.sourceType === "AI").length,
    ).toBeGreaterThan(0);

    await page.close();
  });

  it("refuses copy the project cannot support", async (testContext) => {
    if (!setupDone) {
      void testContext;
      if (!stack.reachable || !stack.available) testContext.skip();
      return;
    }

    const page = await context.newPage();
    await openEditor(page);
    await selectGroundedNode(page);

    await page.getByTestId("editor-tab-ai").click();
    const input = page.getByTestId("editor-propose-input");
    await input.waitFor({ state: "visible", timeout: 15_000 });

    // Snapshot the staged copy so an unchanged stage after the refusal is a
    // meaningful assertion (an earlier test may have applied the variant).
    const staged = page
      .locator('[data-testid="editor-node"][data-node-type="TEXT"]')
      .first();
    await staged.waitFor({ state: "visible", timeout: 15_000 });
    const stagedBefore = (await staged.textContent()) ?? "";

    await input.fill(
      "set text to Northwind Analytics is revolutionary",
    );
    await page.getByTestId("editor-propose-button").click();

    await page
      .getByTestId("editor-ai-error")
      .waitFor({ state: "visible", timeout: 15_000 });
    await expect
      .poll(
        async () => page.getByTestId("editor-ai-error").textContent(),
        { timeout: 15_000 },
      )
      .toContain("cannot support");

    // Nothing was proposed and nothing changed.
    await expect
      .poll(
        async () =>
          page
            .getByTestId("editor-propose-button")
            .evaluate((el) => (el as HTMLButtonElement).disabled === false),
        { timeout: 15_000 },
      )
      .toBe(true);
    expect(await staged.textContent()).toBe(stagedBefore);

    await page.close();
  });
});